// import { BASE_URL } from "./config";
import axios_api from "./axios";
import { apiPath } from "./config";


// const host = `${BASE_URL}/order`;
const host = apiPath("/order/orderlist");

// 전체 주문 조회
export const getOrderList = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 등록
export const createOrderList = async (formData) => {
  const res = await axios_api.post(host, formData);
  return res.data;
};

// 수정
export const updateOrderList = async (orderNo, formData) => {
  const res = await axios_api.put(apiPath(`/order/orderlist/${orderNo}`), formData);
  return res.data;
};

// 상태 값 변경
export const updateOrderStatus = async (orderNo, body) => {
  const res = await axios_api.patch(apiPath(`/order/orderlist/${orderNo}/status`), body);
  return res.data;
};

// 상태 값 완료
export const getCompletedOrders = async () => {
  const res = await axios_api.get(apiPath(`/order/completed`));
  return res.data;
};

// 삭제
export const deleteOrderList = async (orderNo) => {
  const res = await axios_api.delete(apiPath(`/order/orderlist/${orderNo}`));
  return res.data;
};
